from pathlib import Path
import json
root=Path(__file__).resolve().parents[1];pack=json.loads((root/'assets/levels/endless/pack.json').read_text());cards=[]
for c in pack['levels'][28:]:
 level=c['level'];svg=(root/f'assets/levels/endless/figma-editable/Mektra_level_{c["number"]}.svg').read_text()
 cards.append(dict(number=c['number'],name=c['title'],kind=level['segmentKind'],variant=level['variant'],rule=level['instruction'],svg=svg,motions={p['id']:p['motion'] for p in level['platforms']+(level.get('hazards') or []) if p.get('motion')},routes=c['routes'],bounceRuns=level.get('bounceRuns') or []))
page='''<!DOCTYPE html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Mektra — later worlds</title><style>*{box-sizing:border-box}body{margin:0;background:#10151e;color:#edf2fa;font:15px system-ui}header{padding:28px 4vw 16px}h1{margin:0 0 10px;font-size:28px}p{color:#aebbcf;max-width:880px;line-height:1.6}nav{display:flex;flex-wrap:wrap;gap:9px;margin:20px 0}button,a{border:1px solid #39465c;border-radius:8px;padding:10px;background:#1a2535;color:#edf2fa;cursor:pointer;text-decoration:none}button.active{background:#245cc0;border-color:#6aa8ff}main{padding:0 4vw 40px;display:grid;grid-template-columns:repeat(4,minmax(180px,1fr));gap:20px}article{min-width:0}article svg{width:100%;height:auto;border-radius:12px;display:block;background:#9ca3af}h2{font-size:16px;margin:15px 0 8px}.notes{min-height:72px;font-size:13px}article a{display:inline-block;margin:10px 0;font-size:13px}.tools{display:flex;gap:18px;align-items:center;flex-wrap:wrap}label{color:#bfcde0}@media(max-width:950px){main{grid-template-columns:repeat(2,minmax(140px,1fr))}}@media(max-width:500px){main{grid-template-columns:1fr}}</style><header><h1>Mektra · later worlds</h1><p>The opening stays familiar for 16 sections (about 1.7 km). Then eight-section chapters introduce each world, with three recovery sections in every chapter. Later cycles remix earlier mechanics. These are editable source layouts, not a level picker in the game.</p><nav></nav><div class="tools"><label><input id="animate" type="checkbox" checked> Animate shapes</label><label><input id="routes" type="checkbox"> Show authored jump routes</label><span id="unlock"></span></div><p>Mint edges: physical bounce wedges. Orange edges: lethal obstacles. Purple ring: black-hole capture boundary. Tiny mint dots: editable bounce waypoints. Download an SVG to import its vectors into Figma.</p></header><main></main><script>const cards=DATA;let selected=7,start=performance.now();const main=document.querySelector('main'),nav=document.querySelector('nav');for(let k=7;k<14;k++){let b=document.createElement('button');b.textContent=cards.find(c=>c.kind===k).name;b.onclick=()=>{selected=k;render()};b.dataset.kind=k;nav.append(b)}function render(){main.innerHTML='';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',+b.dataset.kind===selected));document.querySelector('#unlock').textContent='First appears at section '+(16+(selected-7)*8);for(const c of cards.filter(c=>c.kind===selected)){let a=document.createElement('article');a.innerHTML='<h2>Variant '+(c.variant+1)+' · layout '+c.number+'</h2><p class="notes">'+c.rule+'</p>'+c.svg+'<a href="../assets/levels/endless/figma-editable/Mektra_level_'+c.number+'.svg" download>Editable SVG</a>';a.dataset.number=c.number;let svg=a.querySelector('svg');let g=document.createElementNS('http://www.w3.org/2000/svg','g');g.dataset.routes='true';const runs=c.bounceRuns.flatMap(run=>run.points.slice(1).map((p,i)=>({launch:run.points[i],landing:p})));for(const r of [...c.routes,...runs]){let l=document.createElementNS(svg.namespaceURI,'line');for(const [key,value] of Object.entries({x1:r.launch.x,y1:r.launch.y,x2:r.landing.x,y2:r.landing.y,stroke:'#4b72ff','stroke-width':2,'stroke-dasharray':'3 8'}))l.setAttribute(key,value);g.append(l)}svg.append(g);main.append(a)}updateRoutes()}function updateRoutes(){document.querySelectorAll('[data-routes]').forEach(g=>g.style.display=document.querySelector('#routes').checked?'':'none')}document.querySelector('#routes').onchange=updateRoutes;function tick(now){if(document.querySelector('#animate').checked){let time=(now-start)/1000;for(const a of main.children){let c=cards.find(c=>c.number===+a.dataset.number);for(const [id,m] of Object.entries(c.motions)){let n=[...a.querySelectorAll('path[id]')].find(n=>n.id.split('__')[0]===id);if(!n)continue;let t=time/m.periodSeconds+m.phase;let rain=m.type==='rain',clock=time/m.periodSeconds,flow=clock+(m.speedVariation||0)*Math.sin(clock*2*Math.PI)/(2*Math.PI)+m.phase,shift=(flow-Math.floor(flow))-m.phase;let x=rain?-m.amplitudeX*shift:m.type==='stream'?-m.amplitudeX*(t-Math.floor(t)):m.amplitudeX*Math.sin(t*2*Math.PI),y=rain?m.amplitudeY*shift:m.type==='stream'?m.amplitudeY*(t-Math.floor(t)):m.amplitudeY*Math.sin(t*2*Math.PI);n.setAttribute('transform','translate('+x+' '+y+')');for(const star of a.querySelectorAll('[id]'))if(star.id.split('__follow__')[1]===id)star.setAttribute('transform','translate('+x+' '+y+')')}}}requestAnimationFrame(tick)}render();requestAnimationFrame(tick);</script></html>'''.replace('DATA',json.dumps(cards,separators=(',',':')).replace('</','<\\/'))
(root/'figma/worlds-preview.html').write_text(page)
